#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_POOL_SIZE 4096
#define BLOCK_SIZE 64
#define MAX_CALLBACKS 32

typedef struct block {
    char data[BLOCK_SIZE];
    int in_use;
    int ref_count;
    struct block *next_free;
} block_t;

typedef struct {
    block_t pool[MAX_POOL_SIZE / BLOCK_SIZE];
    block_t *free_list;
    pthread_mutex_t lock;
    int initialized;
} pool_t;

typedef void (*event_cb)(void *ctx, const char *data, size_t len);

typedef struct {
    event_cb callbacks[MAX_CALLBACKS];
    void *contexts[MAX_CALLBACKS];
    int num_callbacks;
    pool_t *pool;
} event_dispatcher_t;

static pool_t g_pool;
static event_dispatcher_t g_dispatcher;

void pool_init(pool_t *p) {
    pthread_mutex_init(&p->lock, NULL);
    p->free_list = &p->pool[0];
    for (int i = 0; i < (MAX_POOL_SIZE / BLOCK_SIZE) - 1; i++) {
        p->pool[i].next_free = &p->pool[i + 1];
        p->pool[i].in_use = 0;
        p->pool[i].ref_count = 0;
    }
    p->pool[(MAX_POOL_SIZE / BLOCK_SIZE) - 1].next_free = NULL;
    p->pool[(MAX_POOL_SIZE / BLOCK_SIZE) - 1].in_use = 0;
    p->pool[(MAX_POOL_SIZE / BLOCK_SIZE) - 1].ref_count = 0;
    p->initialized = 1;
}

block_t *pool_alloc(pool_t *p) {
    pthread_mutex_lock(&p->lock);
    if (!p->free_list) {
        pthread_mutex_unlock(&p->lock);
        return NULL;
    }
    block_t *b = p->free_list;
    p->free_list = b->next_free;
    b->in_use = 1;
    b->ref_count = 1;
    b->next_free = NULL;
    pthread_mutex_unlock(&p->lock);
    return b;
}

void pool_addref(pool_t *p, block_t *b) {
    pthread_mutex_lock(&p->lock);
    if (b->in_use) {
        b->ref_count++;
    }
    pthread_mutex_unlock(&p->lock);
}

void pool_release(pool_t *p, block_t *b) {
    pthread_mutex_lock(&p->lock);
    if (b->ref_count > 0) {
        b->ref_count--;
    }
    /* Return to free list when ref_count hits zero */
    if (b->ref_count == 0) {
        b->in_use = 0;
        memset(b->data, 0, BLOCK_SIZE);
        b->next_free = p->free_list;
        p->free_list = b;
    }
    pthread_mutex_unlock(&p->lock);
}

void dispatcher_init(event_dispatcher_t *d, pool_t *p) {
    d->num_callbacks = 0;
    d->pool = p;
    memset(d->callbacks, 0, sizeof(d->callbacks));
    memset(d->contexts, 0, sizeof(d->contexts));
}

int dispatcher_register(event_dispatcher_t *d, event_cb cb, void *ctx) {
    if (d->num_callbacks >= MAX_CALLBACKS) return -1;
    d->callbacks[d->num_callbacks] = cb;
    d->contexts[d->num_callbacks] = ctx;
    d->num_callbacks++;
    return 0;
}

void dispatcher_fire(event_dispatcher_t *d, const char *data, size_t len) {
    for (int i = 0; i < d->num_callbacks; i++) {
        if (d->callbacks[i]) {
            d->callbacks[i](d->contexts[i], data, len);
        }
    }
}

/* Session context that holds a reference to a pool block */
typedef struct {
    block_t *token_block;
    pool_t *pool;
    int session_id;
    int valid;
} session_t;

void session_event_handler(void *ctx, const char *data, size_t len) {
    session_t *sess = (session_t *)ctx;
    if (!sess->valid) return;
    /* Copy event data into session's token block */
    size_t copy_len = len < BLOCK_SIZE ? len : BLOCK_SIZE;
    memcpy(sess->token_block->data, data, copy_len);
}

void session_cleanup_handler(void *ctx, const char *data, size_t len) {
    session_t *sess = (session_t *)ctx;
    if (len >= 7 && memcmp(data, "CLEANUP", 7) == 0) {
        /* Release the block - marks session as cleaned up */
        pool_release(sess->pool, sess->token_block);
        sess->valid = 0;
    }
}

/* The audit handler runs AFTER cleanup and checks valid flag */
void audit_log_handler(void *ctx, const char *data, size_t len) {
    session_t *sess = (session_t *)ctx;
    /* SAFE: checks sess->valid which was set to 0 by cleanup_handler */
    if (sess->valid && sess->session_id > 0) {
        volatile char c = sess->token_block->data[0];
        (void)c;
        printf("Audit[%d]: first byte = 0x%02x\n", sess->session_id, 
               (unsigned char)sess->token_block->data[0]);
    }
}

int process_request(const char *input, size_t input_len) {
    if (input_len == 0 || input_len > 1024) return -1;

    /* Fire event to all handlers */
    dispatcher_fire(&g_dispatcher, input, input_len);
    return 0;
}

int main(int argc, char **argv) {
    pool_init(&g_pool);
    dispatcher_init(&g_dispatcher, &g_pool);

    /* Create a session */
    session_t session;
    session.pool = &g_pool;
    session.token_block = pool_alloc(&g_pool);
    if (!session.token_block) return 1;
    session.session_id = 1;
    session.valid = 1;

    /* Store initial token */
    strncpy(session.token_block->data, "SECRET_TOKEN_DATA", BLOCK_SIZE - 1);
    session.token_block->data[BLOCK_SIZE - 1] = '\0';

    /* Register handlers - order matters! */
    dispatcher_register(&g_dispatcher, session_event_handler, &session);
    dispatcher_register(&g_dispatcher, session_cleanup_handler, &session);
    dispatcher_register(&g_dispatcher, audit_log_handler, &session);

    /* Process input from stdin */
    char buf[1025];
    while (fgets(buf, sizeof(buf), stdin)) {
        size_t len = strlen(buf);
        if (len > 0 && buf[len-1] == '\n') buf[--len] = '\0';
        if (len == 0) continue;
        process_request(buf, len);
    }

    /* Cleanup */
    if (session.valid) {
        pool_release(&g_pool, session.token_block);
    }
    pthread_mutex_destroy(&g_pool.lock);
    return 0;
}
